// ND320 is the product number of the Tandberg TDV 2200/9 S terminal. 8085-based 
// http://www.ndwiki.org/wiki/ND320
// http://www.ndwiki.org/wiki/File:Tdv_2200_9_s_configuration_3_IMG_20210405_133357434.jpg <== SEE COLOURS
// http://www.ndwiki.org/images/c/cf/Tdv_2200_9_s_configuration_3_IMG_20210405_133357434.jpg
// https://sites.google.com/site/tingox/tdv2200



namespace RetroTerm.Core.Fonts
{
    public class FontTDV2200 : FontBase
    {

        public FontTDV2200()
        {
            // Size of the glyph
            Height = 16;
            HeightToUse = 14;
            Width = 8;
            stretchY = 1;
            IncludeBlankSpace = true;

            // TDV 2200/9 S Character Sets (per ND User's Guide)
            // fontNumOffset[0,1] = Character set 1 (Main set) - 95 standard alphanumeric characters
            // fontNumOffset[2] = Character set 2 (ESC A) - Greek alphabet, mathematical characters, graphic symbols
            // fontNumOffset[3] = Character set 3 (ESC 0) - Subscripts, superscripts, special characters
            // fontNumOffset[4] = Character set 4 - Control codes for transparent mode display
            //
            // NOTE: TDV2115 uses DIFFERENT character sets (line drawing at set 2).
            // This font is specifically for TDV2200 which has Greek/Math at set 2.

            fontNumOffset = new ushort[]
            {
                0,
                0,
                128,
                256,
                384
            };

            // The TDV2200 ROM glyph bitmaps, one row of bits per scan line.
            // Geometry:
            //  - Each glyph starts at x+1, y+2 within its cell.
            //  - Each glyph is 10 bits wide and 8 rows tall.
            //  - The table holds 1023 glyphs.
            glyphs = new ushort[]
                    {
