        private int _characterSetVariant = 0;

        /// <summary>
        /// Active ISO 646 national variant for character set 1.
        /// 0 = International, 1 = Norwegian/Danish, 2 = Swedish, 3 = German.
        ///
        /// On a real TDV2200 the character-generator ROM displays national characters at the
        /// ISO 646 wire positions (0x5B-0x5E, 0x7B-0x7E) when the corresponding national variant
        /// is selected. The host sends 7-bit ASCII position bytes (e.g. '[' = 0x5B for Æ) and the
        /// terminal renders the national glyph. When this is non-International, GetFontBits remaps
        /// those wire positions to the national glyphs stored elsewhere in the ROM (0x00-0x1F range).
        /// </summary>
        public override int CharacterSetVariant
        {
            get => _characterSetVariant;
            set
            {
                if (value < 0 || value > 3) value = 0;
                _characterSetVariant = value;
            }
        }

        /// <summary>
        /// Returns the bitmap rows for one character, honouring the selected ISO 646 variant.
        /// </summary>
        /// <param name="fontValue">
        /// The character's position in the ROM, which for an ordinary character is its code.
        /// </param>
        /// <param name="fontNum">
        /// Which character set to take it from - 0 and 1 are character set 1, and they are the only
        /// ones a national variant can affect.
        /// </param>
        /// <returns>
        /// The glyph bit rows, or null when the ROM has no glyph at that position.
        /// </returns>
        /// <remarks>
        /// <para><b>Why the remap lives here and not in the parser</b></para>
        /// On a real TDV2200 the character generator holds the national glyphs elsewhere in the
        /// ROM and displays them AT the ISO 646 wire positions when a variant is selected. The host
        /// goes on sending 7-bit positions - a left square bracket for the Norwegian AE, and so on -
        /// so nothing upstream of the font knows a variant is in force. Doing the remap at the last
        /// moment keeps the buffer holding what the host actually sent, which is what makes a copy
        /// out of the screen come back as the host's own bytes.
        /// </remarks>
        public override ushort[]? GetFontBits(ushort fontValue, int fontNum)
        {
            // National variants only affect character set 1 (fontNum 0/1) at the ISO 646 positions.
            if (_characterSetVariant != 0 && (fontNum == 0 || fontNum == 1) && fontValue < 0x80)
            {
                // Glyphs that do not exist in the ROM are synthesized directly.
                if (_characterSetVariant == 2) // Swedish
                {
                    if (fontValue == 0x5C) return (ushort[])OUmlautUpperGlyph.Clone(); // Ö
                }
                else if (_characterSetVariant == 3) // German
                {
                    if (fontValue == 0x5C) return (ushort[])OUmlautUpperGlyph.Clone(); // Ö
                    if (fontValue == 0x7E) return (ushort[])SharpSGlyph.Clone();       // ß
                }

                int romIndex = RemapNationalGlyph(fontValue, _characterSetVariant);
                if (romIndex >= 0)
                    return base.GetFontBits((ushort)romIndex, fontNum);
            }

            return base.GetFontBits(fontValue, fontNum);
        }

        /// <summary>
        /// Maps an ISO 646 wire position to the ROM glyph index that holds the national character
        /// for the given variant. Returns -1 when the position is unchanged for that variant.
        /// ROM glyph indices below were confirmed from the TDV2200 font ROM (0x00-0x1F range).
        /// </summary>
        private static int RemapNationalGlyph(ushort fontValue, int variant)
        {
            switch (variant)
            {
                case 1: // Norwegian / Danish
                    switch (fontValue)
                    {
                        case 0x5B: return 0x05; // Æ
                        case 0x5C: return 0x06; // Ø
                        case 0x5D: return 0x02; // Å
                        case 0x7B: return 0x10; // æ
                        case 0x7C: return 0x1D; // ø
                        case 0x7D: return 0x16; // å
                        default: return -1;
                    }
                case 2: // Swedish (0x5C -> Ö handled by caller)
                    switch (fontValue)
                    {
                        case 0x5B: return 0x01; // Ä
                        case 0x5D: return 0x02; // Å
                        case 0x7B: return 0x11; // ä
                        case 0x7C: return 0x1C; // ö
                        case 0x7D: return 0x16; // å
                        default: return -1;
                    }
                case 3: // German (0x5C -> Ö, 0x7E -> ß handled by caller)
                    switch (fontValue)
                    {
                        case 0x5B: return 0x01; // Ä
                        case 0x5D: return 0x04; // Ü
                        case 0x7B: return 0x11; // ä
                        case 0x7C: return 0x1C; // ö
                        case 0x7D: return 0x0A; // ü
                        default: return -1;
                    }
                default:
                    return -1;
            }
        }

        // Uppercase Ö (O with umlaut). The TDV2200 ROM dump has no Ö glyph, so it is synthesized
        // in the same style as the ROM's national uppercase letters (Ä = 0x01, Ü = 0x04):
        // row 1 = umlaut dots, rows 3-9 = the letter body.
        private static readonly ushort[] OUmlautUpperGlyph = new ushort[]
        {
            0x0000, 0x0044, 0x0000, 0x007C, 0x0082, 0x0082, 0x0082, 0x0082, 0x0082, 0x007C,
            0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000
        };

        // German ß (sharp s). The TDV2200 ROM dump has no ß glyph, so it is synthesized here in
        // the ROM's single-stroke style: a tall left stem with two stacked bowls, the lower bowl
        // open on the right, and the stem descending below the baseline (the ß signature vs. a B).
        //   .XXXX...
        //   .X..X...
        //   .X..X...
        //   .XXX....   (waist)
        //   .X..X...
        //   .X..X...
        //   .X..X...
        //   .XXX....   (lower bowl, open right)
        //   .X......
        //   .X......   (descender)
        //   .X......
        private static readonly ushort[] SharpSGlyph = new ushort[]
        {
            0x0000, 0x0078, 0x0048, 0x0048, 0x0070, 0x0048, 0x0048, 0x0048, 0x0070, 0x0040,
            0x0040, 0x0040, 0x0000, 0x0000, 0x0000, 0x0000
        };
    }
}
